const state={bootstrapReady:false,setupAutoCheckCompleted:false,health:null,clientContract:null,resultViewerMode:'case',registry:null,templates:[],tasks:[],selectedTemplate:null,parameterLevel:'basic',selectedTask:null,expertOverrides:{Global:{},EMag:{},Therm:{},Lab:{},Mechanical:{}},expertEntries:[],solverSettings:{EMag:{},Therm:{},Lab:{},Mechanical:{}},solverRaw:{EMag:'',Therm:'',Lab:'',Mechanical:''},solverContext:'EMag',systemSnapshot:null,systemStream:null,taskStream:null,monitorTask:null,monitorEvents:[],eventFilter:'ALL',analytics:null,optimization:null,overlay:null,dataFactory:null,datasets:[],templateCompare:[],workspaceProjects:[],projectManagerRows:[],workspaceProject:null,workspaceDesign:null,workspaceRevision:null,workspaceCreateTemplateId:null,workspaceCreateBusy:false,taskDesignRevisionId:null,projectManagerEditorId:null,projectManagerTrashMode:false,startupInstallation:null,runtimePreflight:null,logs:[],activeProjectId:localStorage.getItem('motorcad-studio-active-project')||null,logSummary:null,logDiagnostics:null,logStream:null,lastLogSeq:0,materialCatalog:null,viewer:null,viewerCatalog:null,systemStreamFailures:0,systemPollTimer:null,language:(window.MCS_I18N?.language||'zh')};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
window.MCSAppState=state;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
