const humanApiDetail=detail=>{if(typeof detail==='string')return detail;if(Array.isArray(detail))return detail.map(row=>{const where=Array.isArray(row?.loc)?row.loc.filter(x=>x!=='body').join(' › '):'';return `${where?where+'：':''}${row?.msg||row?.message||'输入不符合要求'}`}).join('；');if(detail&&typeof detail==='object'){const main=detail.message||detail.error||detail.reason||detail.title;if(main)return String(main);const messages=Object.values(detail).filter(v=>typeof v==='string');if(messages.length)return messages.join('；')}return'请求未完成，请查看“问题”中的技术详情。'};
const api=async(url,options={})=>{const r=await fetch(url,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const requestId=r.headers.get('X-Request-ID');if(!r.ok){let body;try{body=await r.json()}catch{body={detail:await r.text()}};const base=humanApiDetail(body.detail);const err=new Error(requestId?`${base} · Request ${requestId}`:base);err.requestId=requestId;err.status=r.status;err.detail=body.detail;throw err}return r.json()};

function showTab(id){if(id==='analysisWorkbench'||id==='newTask'||id==='simulationAssets')id='analysisConfig';const projectScoped=new Set(['dashboard','solutions','workspace','templates','analysisConfig','monitor','tasks','resultViewer','dataFactory']);if(projectScoped.has(id)&&!state.activeProjectId){toast(uiText('请先在“项目管理”中进入一个项目。项目内部页面不提供跨项目切换。','Enter a project from Project Management first. Project pages do not provide cross-project switching.'),'WARNING',6500);id='projects'}$$('.tab').forEach(x=>x.classList.toggle('active',x.id===id));$$('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));if(state.routeOwnsLoadV025)return;if(id==='setup')loadStartupSetup(false);if(id==='projects')loadProjectManager();if(id==='dashboard')loadDashboard();if(id==='solutions')window.MCSCanonicalFlow?.mountSolutions?.();if(id==='workspace')loadWorkspace();if(id==='analysisConfig')window.MCSUnifiedAnalysis?.mount?.({tab:'analysisConfig',projectId:state.activeProjectId},null);if(id==='monitor')loadMonitorLanding();if(id==='tasks')loadTasks();if(id==='dataFactory')loadDataFactory();if(id==='resultViewer'){loadResultViewerLanding();loadAnalyticsLanding()}if(id==='logs')loadLogs();if(id==='system')loadSystemOverview()}
