async function init(){
  [state.health,state.registry,state.templates,state.workspaceProjects]=await Promise.all([api('/api/health'),api('/api/registry'),api('/api/templates'),api('/api/projects')]);
  if(state.activeProjectId&&!state.workspaceProjects.some(p=>p.id===state.activeProjectId))setActiveProject(null);
  syncProjectContextSelectors();
  try{state.clientContract=await api('/api/client-contract')}catch(e){state.clientContract=null}
  const frontendVersion=document.documentElement.dataset.studioVersion||'';const backendVersion=state.health.version||'';const banner=$('#compatBanner');
  if(banner&&(frontendVersion!==backendVersion||!state.clientContract)){banner.classList.remove('hidden');banner.innerHTML=`<b>前后端版本可能不一致</b><span>前端 ${esc(frontendVersion||'-')} / 后端 ${esc(backendVersion||'-')}。请停止旧服务并从同一版本目录重新启动；当前版本已禁用静态资源缓存，以避免旧JS继续请求不存在的API。</span>`}
  const hb=$('#healthBadge');hb.textContent=`服务正常 · ${state.health.version}`;hb.classList.add('ok');
  const motor=state.health.solvers.motorcad;const sb=$('#solverBadge');sb.textContent=motor.available?`PyMotorCAD 可用${motor.pymotorcad_version?' · '+motor.pymotorcad_version:''}`:'PyMotorCAD 未连接';sb.classList.add(motor.available?'ok':'warn');
  fillStaticOptions();renderTemplates();
  if($('#templateSelect'))renderTemplateSelect();
  if($('#analysis')&&$('#outputFields'))renderOutputs();
  if($('#parameterGroups'))renderParameterGroups();
  updateProjectNavState();
  state.bootstrapReady=true;
  window.dispatchEvent(new CustomEvent('mcs:bootstrap-ready',{detail:{version:state.health?.version||null}}));
}

function fillStaticOptions(){
  const sectors=[...new Set(state.templates.map(t=>t.sector))].filter(Boolean).sort();
  const templateFilter=$('#templateFilter');if(templateFilter)templateFilter.innerHTML='<option value="">全部领域</option>'+sectors.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
  const scenario=state.registry?.scenario||{};
  const coolingType=$('#coolingType');if(coolingType)coolingType.innerHTML=(scenario.cooling_types||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('');
  const initialCondition=$('#initialCondition');if(initialCondition)initialCondition.innerHTML=(scenario.initial_condition_modes||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('');
  const qualityProfile=$('#qualityProfile');if(qualityProfile)qualityProfile.innerHTML=Object.entries(state.registry?.quality_profiles||{}).map(([id,d])=>`<option value="${esc(id)}" ${id==='standard'?'selected':''}>${esc(d.label||id)}</option>`).join('');
  const analysis=$('#analysis');if(analysis){const recipes=state.registry?.analysis_recipes||{};analysis.innerHTML=Object.entries(recipes).map(([id,d])=>`<option value="${esc(id)}">${esc(d.label||id)}${d.production_ready?'':'（待实机验证）'}</option>`).join('')}
  const automationMachineType=$('#automationMachineType');if(automationMachineType){const motorTypes=[...new Set(state.templates.map(t=>t.motor_type).filter(Boolean))].sort();automationMachineType.innerHTML=motorTypes.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}
  const automationVersion=$('#automationVersion');if(automationVersion)automationVersion.value=state.registry?.motorcad_version||'2026R1';
  const expertContext=$('#expertContext');if(expertContext){state.solverContext=expertContext.value;renderSolverControls();const solverSettings=$('#solverSettings');if(solverSettings)solverSettings.value=state.solverRaw[state.solverContext]||''}
}

async function loadDashboard(){
  const d=await api('/api/dashboard'+projectQuery());const metrics=[['模板总数',d.templates.total],['精选候选',d.templates.curated],['轴向模板',d.templates.axial],['任务总数',d.tasks.total],['运行中',d.tasks.running],['累计Case',d.tasks.cases]];$('#dashboardMetrics').innerHTML=metrics.map(([k,v])=>`<div class="metric-card"><span>${k}</span><b>${v}</b></div>`).join('');
  const sectors=Object.entries(d.templates.by_sector||{}).sort((a,b)=>b[1]-a[1]);const max=Math.max(...sectors.map(x=>x[1]),1);$('#templateStats').innerHTML=sectors.map(([name,count])=>`<div class="bar-row"><span>${esc(name)}</span><div class="bar-track"><span style="width:${count/max*100}%"></span></div><b>${count}</b></div>`).join('');
  $('#recentTasks').innerHTML=d.recent_tasks.length?d.recent_tasks.map(renderCompactTask).join(''):'<p class="muted">尚无任务</p>';
  if(state.systemSnapshot)renderSystemSnapshot(state.systemSnapshot);
}
function renderCompactTask(t){return `<div class="task-item" data-open-task="${esc(t.id)}"><div class="task-top"><div><div class="task-title">${esc(t.name)}</div><div class="muted">${esc(t.analysis_label||t.analysis||'计算分析')} · ${esc(experimentModeLabel(t.request?.experiment?.mode))}</div></div><span class="status ${esc(t.status)}">${esc(viewerStatusLabel(t.status))}</span></div><div class="progress"><span style="width:${Math.round((t.progress||0)*100)}%"></span></div><div class="muted">${Math.round((t.progress||0)*100)}% · ${Number(t.usable_cases||0)} 个结果可用</div></div>`}

document.addEventListener('click',e=>{const target=e.target.closest('[data-open-task]');if(target){window.MCSEngineeringContext?.setExecution?.(target.dataset.openTask,{taskId:target.dataset.openTask,kind:'task',source:'app:open-task-link'});if(!window.MCSEngineeringContext)state.selectedTask=target.dataset.openTask;if(window.MCSRouter?.navigate){MCSRouter.navigate(`/app/projects/${encodeURIComponent(state.activeProjectId)}/simulation/tasks/${encodeURIComponent(target.dataset.openTask)}`)}else{showTab('tasks');showTask(target.dataset.openTask)}}});

function motorSchematic(t,large=false,parameters=null){
  const p=parameters||{};
  const axial=Boolean(t&&t.is_axial);
  const top=String((t&&t.topology)||(t&&t.motor_type)||'').toUpperCase();
  const poles=Math.max(2,Math.min(24,Math.round(Number(p.pole_count??(t&&t.poles))||8)));
  const slots=Math.max(3,Math.min(72,Math.round(Number(p.slot_count??(t&&t.slots))||12)));
  const od=Math.max(1,Number(p.stator_outer_diameter??t?.defaults?.stator_outer_diameter??80)||80);
  const bore=Math.max(1,Math.min(od*.92,Number(p.stator_inner_diameter??t?.defaults?.stator_inner_diameter??od*.52)||od*.52));
  const gap=Math.max(.05,Number(p.air_gap??t?.defaults?.air_gap??.8)||.8);
  const magnetThickness=Math.max(.1,Number(p.magnet_thickness??t?.defaults?.magnet_thickness??3)||3);
  if(axial){
    let magnets='';const shown=Math.min(16,poles);const magnetW=Math.max(5,Math.min(12,120/shown));
    for(let i=0;i<shown;i+=1){const x=42+i*(130/Math.max(1,shown-1));magnets+=`<rect x="${(x-magnetW/2).toFixed(1)}" y="34" width="${magnetW.toFixed(1)}" height="${Math.max(7,Math.min(14,magnetThickness*3)).toFixed(1)}" rx="2" data-schematic-part="magnet" class="${i%2?'magnet-b':'magnet-a'}"/>`;}
    return `<div class="template-schematic ${large?'large':''}"><svg viewBox="0 0 220 130" aria-label="轴向磁通电机参数随动示意图"><rect x="28" y="20" width="164" height="14" rx="5" data-schematic-part="rotor" class="rotor"/>${magnets}<rect x="34" y="52" width="152" height="8" rx="3" data-schematic-part="airgap" class="airgap"/><rect x="38" y="63" width="144" height="24" rx="5" data-schematic-part="stator stator-slot" class="stator"/><rect x="34" y="90" width="152" height="8" rx="3" data-schematic-part="airgap" class="airgap"/><rect x="28" y="101" width="164" height="14" rx="5" data-schematic-part="rotor" class="rotor"/><text x="110" y="15" text-anchor="middle">AFPM · ${esc(top)}</text><text x="110" y="79" text-anchor="middle">${esc(poles)} 极 · ${esc(slots)} 槽</text></svg></div>`;
  }
  const cx=110,cy=66,outerR=50;
  const boreR=Math.max(24,Math.min(42,outerR*(bore/od)));
  const gapPx=Math.max(1.3,Math.min(4.2,outerR*(2*gap/od)));
  const rotorR=Math.max(14,boreR-gapPx);
  const statorMid=(outerR+boreR)/2,statorStroke=Math.max(7,outerR-boreR);
  const shaftR=Math.max(8,rotorR*.28);
  const magR=Math.max(3.2,Math.min(7.5,3.3+magnetThickness*.55));
  let teeth='',magnets='';
  for(let i=0;i<slots;i+=1){const a=i*2*Math.PI/slots;const x1=cx+(boreR+1)*Math.cos(a),y1=cy+(boreR+1)*Math.sin(a),x2=cx+(outerR-1)*Math.cos(a),y2=cy+(outerR-1)*Math.sin(a);teeth+=`<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" data-schematic-part="stator-slot" stroke="#667085" stroke-width="${slots>36?1.4:2.4}"/>`;}
  for(let i=0;i<poles;i+=1){const a=i*2*Math.PI/poles;const rr=Math.max(shaftR+magR+2,rotorR-magR-2),x=cx+rr*Math.cos(a),y=cy+rr*Math.sin(a);magnets+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${magR.toFixed(1)}" data-schematic-part="magnet" class="${i%2?'magnet-b':'magnet-a'}"/>`;}
  return `<div class="template-schematic ${large?'large':''}"><svg viewBox="0 0 220 132" aria-label="径向磁通电机参数随动示意图"><circle cx="${cx}" cy="${cy}" r="${statorMid.toFixed(1)}" data-schematic-part="stator" fill="none" stroke="#98a2b3" stroke-width="${statorStroke.toFixed(1)}"/>${teeth}<circle cx="${cx}" cy="${cy}" r="${rotorR.toFixed(1)}" data-schematic-part="rotor" class="rotor"/>${magnets}<circle cx="${cx}" cy="${cy}" r="${shaftR.toFixed(1)}" data-schematic-part="shaft" class="shaft"/><circle cx="${cx}" cy="${cy}" r="${(boreR-gapPx*.45).toFixed(1)}" data-schematic-part="airgap" fill="none" class="airgap"/><text x="110" y="13" text-anchor="middle">RFPM · ${esc(poles)} 极 / ${esc(slots)} 槽</text></svg></div>`;
}

function maturityLabel(m){return ({verified_candidate:'验证候选',research_candidate:'研究候选',result_reference:'结果参考',adaptive_reference:'自适应参考',raw_reference:'原始参考'})[m]||m||'未分类'}
function renderTemplateCompareTray(){const bar=$('#templateCompareBar');if(!bar)return;bar.classList.toggle('hidden',!state.templateCompare.length);$('#templateCompareCount').textContent=state.templateCompare.length;$('#templateCompareNames').innerHTML=state.templateCompare.map(id=>`<span class="compare-chip">${esc(id)}</span>`).join('')}
function toggleTemplateCompare(id){const i=state.templateCompare.indexOf(id);if(i>=0)state.templateCompare.splice(i,1);else if(state.templateCompare.length<3)state.templateCompare.push(id);else return toast('最多同时比较3个模板','WARNING');renderTemplates();renderTemplateCompareTray()}
function showTemplateCompare(){if(state.templateCompare.length<2)return toast('至少选择2个模板进行比较','WARNING');const list=state.templateCompare.map(id=>state.templates.find(t=>t.id===id)).filter(Boolean),fields=[['拓扑','topology'],['Motor Type','motor_type'],['成熟度','maturity'],['功率/kW','power_note'],['转速/rpm','speed_note'],['极数','poles'],['槽数','slots'],['气隙/mm','airgap'],['冷却','cooling_note'],['版本','version']];const el=$('#templateDetail');el.classList.remove('hidden');el.innerHTML=`<div class="section-head"><div><h2>模板工程比较</h2><p>${list.length} 个候选模板</p></div><button id="closeTemplateDetail">关闭</button></div><table class="template-compare-table"><thead><tr><th>属性</th>${list.map(t=>`<th>${esc(t.id)}</th>`).join('')}</tr></thead><tbody>${fields.map(([label,key])=>`<tr><th>${esc(label)}</th>${list.map(t=>`<td>${key==='maturity'?esc(maturityLabel(t[key])):esc(t[key]??'-')}</td>`).join('')}</tr>`).join('')}<tr><th>能力</th>${list.map(t=>`<td>${Object.entries(t.capabilities?.motorcad||{}).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join('<br>')}</td>`).join('')}</tr></tbody></table>`;$('#closeTemplateDetail').addEventListener('click',()=>el.classList.add('hidden'))}

function renderTemplates(){
  const q=$('#templateSearch').value.trim().toLowerCase(),sector=$('#templateFilter').value,maturity=$('#templateMaturity').value,axial=$('#axialOnly').checked;
  const list=state.templates.filter(t=>!sector||t.sector===sector).filter(t=>!maturity||t.maturity===maturity).filter(t=>!axial||t.is_axial).filter(t=>!q||JSON.stringify([t.id,t.topology,t.sector,t.application,t.tags,t.description]).toLowerCase().includes(q));
  const useLabel=state.activeProjectId?uiText('在当前项目中创建设计','Create design in current project'):uiText('进入项目后使用','Enter a project to use');
  $('#templateGrid').innerHTML=list.map(t=>{const qs=Object.values(t.runtime_qualification||{}),best=qs.length?Math.max(...qs.map(x=>Number(x.level)||0)):0;const qBadge=best?`<span class="chip ${best>=4?'verified-runtime':'warning'}">Motor-CAD L${best}</span>`:`<span class="chip muted-chip">未实机资格</span>`;return `<article class="card ${t.recommended?'recommended':''}">${motorSchematic(t)}<div class="template-validation"><span class="maturity-dot ${esc(t.maturity)}">${esc(maturityLabel(t.maturity))}</span><span class="hint">${esc(t.version||'-')}</span></div><h3>${esc(t.id)}</h3><div class="meta"><span class="chip primary">${esc(t.topology)}</span><span class="chip">${esc(t.sector)}</span><span class="chip">${esc(t.motor_type)}</span>${qBadge}${t.recommended?'<span class="chip primary">推荐</span>':''}${t.is_axial?'<span class="chip warning">轴向</span>':''}</div><p>${esc(t.description)}</p><p class="muted">${esc(t.power_note||'-')} kW · ${esc(t.speed_note||'-')} rpm · ${esc(t.poles||'-')}极${esc(t.slots||'-')}槽</p><div class="card-actions"><button data-template-detail="${esc(t.id)}">详情</button><button data-template-compare="${esc(t.id)}">${state.templateCompare.includes(t.id)?'移出比较':'加入比较'}</button><button class="primary" data-use-template="${esc(t.id)}">${esc(useLabel)}</button></div></article>`}).join('')||'<p class="muted">没有匹配模板</p>';renderTemplateCompareTray();
}
['templateSearch','templateFilter','templateMaturity','axialOnly'].forEach(id=>$('#'+id)?.addEventListener(id==='templateSearch'?'input':'change',renderTemplates));
function beginWorkspaceDesignFromTemplate(templateId){const t=state.templates.find(x=>x.id===templateId);if(!t)return;if(!state.activeProjectId){toast(uiText('请先在项目管理中进入一个项目，再从模板创建设计。','Enter a project from Project Management before creating a design from a template.'),'WARNING',6500);showTab('projects');return}state.selectedTemplate=t;state.workspaceCreateTemplateId=t.id;state.workspaceCreateBusy=false;$('#templateDetail')?.classList.add('hidden');toast(uiText(`已选择 ${t.id}，请确认Design名称后创建Rev.1。`,`Selected ${t.id}. Confirm the Design name to create Rev.1.`),'INFO',4500);showTab('workspace')}
document.addEventListener('click',e=>{const d=e.target.closest('[data-template-detail]');if(d)showTemplateDetail(d.dataset.templateDetail);const c=e.target.closest('[data-template-compare]');if(c)toggleTemplateCompare(c.dataset.templateCompare);const u=e.target.closest('[data-use-template]');if(u)beginWorkspaceDesignFromTemplate(u.dataset.useTemplate)});$('#openTemplateCompare')?.addEventListener('click',showTemplateCompare);$('#clearTemplateCompare')?.addEventListener('click',()=>{state.templateCompare=[];renderTemplates();renderTemplateCompareTray()});
function showTemplateDetail(id){const t=state.templates.find(x=>x.id===id);if(!t)return;const el=$('#templateDetail');el.classList.remove('hidden');el.innerHTML=`<div class="section-head"><div><h2>${esc(t.id)}</h2><p>${esc(t.system_template_id)}</p></div><button id="closeTemplateDetail">关闭</button></div>${motorSchematic(t,true)}<p>${esc(t.description)}</p><div class="definition-grid">${[['拓扑',t.topology],['应用',t.application],['Motor-CAD版本',t.version],['成熟度',t.maturity],['功率',`${t.power_note||'-'} kW`],['转速',`${t.speed_note||'-'} rpm`],['槽极',`${t.slots||'-'}槽 / ${t.poles||'-'}极`],['气隙',`${t.airgap||'-'} mm`],['冷却',t.cooling_note],['参数白名单',`${t.parameter_ids.length}项`]].map(([k,v])=>`<div class="definition-item"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div><h3>能力矩阵</h3>${Object.entries(t.capabilities.motorcad||{}).map(([k,v])=>`<div class="definition-item"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}<h3>使用提示</h3>${(t.warnings||[]).map(x=>`<div class="issue WARNING">${esc(x)}</div>`).join('')||'<p class="muted">无专项提示</p>'}<div class="actions"><button class="primary" data-use-template="${esc(t.id)}">在当前项目中创建设计</button></div>`;$('#closeTemplateDetail').addEventListener('click',()=>el.classList.add('hidden'))}

