async function showTask(id,routeCtx=null){
  window.MCSEngineeringContext?.setExecution?.(id,{taskId:id,kind:'task',source:'app:show-task'});if(!window.MCSEngineeringContext)state.selectedTask=id;
  const options=routeCtx?.signal?{signal:routeCtx.signal}:{};
  const [t,page,events,diagnosis]=await Promise.all([
    api('/api/tasks/'+id+'/summary',options),
    api('/api/tasks/'+id+'/cases?offset=0&limit=200',options),
    api('/api/tasks/'+id+'/events?limit=200',options),
    api('/api/logs/diagnostics?minutes=1440&limit=5&task_id='+encodeURIComponent(id),options),
  ]);
  if(routeCtx&&!window.MCSPageRuntime?.isContextActive?.(routeCtx))return null;
  t.cases=page.items||[];t.events=events||[];
  const d=$('#taskDetail');d.classList.remove('hidden');
  const canCancel=['QUEUED','RUNNING','RECOVERING'].includes(t.status);const canRetry=['FAILED','PARTIALLY_COMPLETED','CANCELLED'].includes(t.status);
  const caseNote=page.total>page.items.length?`<p class="muted">页面显示前 ${page.items.length}/${page.total} 个工况；“完整数据包”保留全部记录。</p>`:'';
  const humanStageValue=value=>window.MCSSolverEvidence?.humanStage?.(value)||String(value||'等待').replaceAll('_',' '),taskState=viewerStatusLabel(t.status),solveLabel=window.MCSAnalysisLabels?.solveModeLabel?.(t.solver_mode)||t.solver_mode||'计算';
  d.innerHTML=`<div class="section-head"><div><h2>${esc(t.name)}</h2><p>${esc(t.analysis_label||t.analysis)} · ${esc(solveLabel)} · ${esc(t.template_name||'当前电机模型')}</p><small class="case-technical-id-v058">任务记录 ${esc(t.id)}</small></div><span class="status ${esc(t.status)}">${esc(taskState)}</span></div>${taskRootDiagnosisHtml(diagnosis)}<div class="actions"><button type="button" id="openTaskResults" class="primary">查看工程结果</button><a href="/api/tasks/${esc(id)}/report.html" target="_blank"><button>打开工程报告</button></a><a href="/api/tasks/${esc(id)}/export.csv"><button>导出结果表</button></a><a href="/api/tasks/${esc(id)}/export.zip"><button>下载完整数据包</button></a><a href="/api/logs/export.zip?task_id=${encodeURIComponent(id)}&minutes=1440"><button>下载任务诊断包</button></a>${canCancel?'<button id="cancelTask">完成当前工况后停止</button><button id="forceCancelTask" class="danger">立即终止当前工况</button>':''}${canRetry?'<button id="retryTask" class="primary">重试失败工况</button>':''}</div><div class="divider"></div><div class="definition-grid">${[['任务状态',taskState],['总进度',`${Math.round((t.progress||0)*100)}%`],['当前步骤',humanStageValue(t.current_stage)],['分析方式',t.request?.experiment?.mode==='single'?'单次计算':'批量工况'],['工况数',t.case_count],['结果验证规则',t.quality_profile||'默认规则'],['创建时间',t.created_at?new Date(t.created_at).toLocaleString():'—']].map(([k,v])=>`<div class="definition-item"><span>${esc(k)}</span><b>${esc(v??'-')}</b></div>`).join('')}</div><h3>工况记录</h3>${caseNote}<div>${t.cases.map((row,index)=>renderCase(row,index)).join('')}</div><h3>最近运行记录</h3><div class="event-list">${(t.events||[]).slice(-100).reverse().map(ev=>`<div class="event ${esc(ev.severity)}"><span>${esc(ev.severity==='ERROR'?'错误':ev.severity==='WARNING'?'提示':'信息')}</span><span>${esc(humanStageValue(ev.stage||ev.event_type))}</span><span>${esc(ev.message)}</span></div>`).join('')||'<div class="muted">暂无运行记录</div>'}</div>`;
  $$('.case-head').forEach(h=>h.addEventListener('click',()=>$('#'+h.dataset.body).classList.toggle('hidden')));
  const runTaskAction=async(button,url,body,confirmation,working)=>{if(confirmation){const approved=window.StudioDialog?.confirm?await StudioDialog.confirm({title:body.mode==='terminate_current'?'确认立即终止计算':'确认停止后续计算',message:confirmation,confirmText:body.mode==='terminate_current'?'立即终止':'停止后续计算',danger:body.mode==='terminate_current'}):window.confirm(confirmation);if(!approved)return}const old=button.textContent;button.disabled=true;button.textContent=working;try{await api(url,{method:'POST',body:JSON.stringify(body)});await showTask(id)}catch(error){button.disabled=false;button.textContent=old;toast(`操作失败：${error.message}`,'ERROR',8000)}};
  if($('#cancelTask'))$('#cancelTask').addEventListener('click',event=>runTaskAction(event.currentTarget,`/api/tasks/${id}/cancel`,{mode:'stop_after_current'},'确认完成当前工况后停止后续计算？已经完成的工况结果会保留。','正在请求停止…'));
  if($('#forceCancelTask'))$('#forceCancelTask').addEventListener('click',event=>runTaskAction(event.currentTarget,`/api/tasks/${id}/cancel`,{mode:'terminate_current'},'立即终止会中断当前 Motor-CAD 工况。确认继续？','正在终止…'));
  if($('#retryTask'))$('#retryTask').addEventListener('click',event=>runTaskAction(event.currentTarget,`/api/tasks/${id}/retry`,{failed_only:true},'', '正在重新排队…'));
  if($('#openTaskResults'))$('#openTaskResults').addEventListener('click',()=>{setResultViewerMode('case');if(window.MCSRouter?.navigate)MCSRouter.navigate(`/app/projects/${encodeURIComponent(state.activeProjectId)}/results/tasks/${encodeURIComponent(id)}`);else showTab('resultViewer')});
  drawVisibleCharts();
  return t;
}
function renderCase(c,index=0){const result=c.result||{},flags=result.quality_flags||[],scalars=result.scalars||{},bodyId='body-'+c.id.replace(/[^a-zA-Z0-9]/g,''),seriesKey=Object.keys(result.series||{})[0],execution=viewerStatusLabel(c.execution_status||c.status),quality=viewerStatusLabel(c.quality_status);return `<div class="case-card"><div class="case-head" data-body="${bodyId}"><b>工况 ${index+1}</b><span class="status ${esc(c.execution_status||c.status)}">${esc(execution)}</span><span class="status ${esc(c.quality_status||'')}">${esc(quality)}</span><span>${Math.round((c.progress||0)*100)}%</span><button type="button">查看</button></div><div id="${bodyId}" class="case-body hidden"><div class="result-grid">${Object.entries(scalars).map(([k,v])=>{const o=state.registry.outputs[k]||{};return `<div class="result-metric"><span>${esc(o.label||k)}${o.unit?' / '+esc(o.unit):''}</span><b>${esc(v??'-')}</b></div>`}).join('')||'<p class="muted">尚无可用结果</p>'}</div><div class="flag-list">${flags.map(f=>`<span class="flag ${esc(f.severity)}">${esc(f.message||'结果验证提示')}</span>`).join('')}</div>${seriesKey?`<svg class="mini-chart" data-series='${esc(JSON.stringify(result.series[seriesKey]))}' role="img" aria-label="${esc(state.registry.outputs?.[seriesKey]?.label||'结果曲线')}"></svg>`:''}${c.error?`<details class="developer-only"><summary>技术错误信息</summary><pre class="error-text">${esc(c.error)}</pre></details>`:''}</div></div>`}
function drawVisibleCharts(){$$('.mini-chart').forEach(svg=>{let s;try{s=JSON.parse(svg.dataset.series)}catch{return}const x=s.x||[],y=s.y||[];if(x.length<2||y.length<2)return;const w=600,h=190,p=28,xmin=Math.min(...x),xmax=Math.max(...x),ymin=Math.min(...y),ymax=Math.max(...y);const px=v=>p+(v-xmin)/(xmax-xmin||1)*(w-2*p),py=v=>h-p-(v-ymin)/(ymax-ymin||1)*(h-2*p);const points=x.map((v,i)=>`${px(v)},${py(y[i])}`).join(' ');svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=`<line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" stroke="#98a2b3"/><line x1="${p}" y1="${p}" x2="${p}" y2="${h-p}" stroke="#98a2b3"/><polyline fill="none" stroke="#175cd3" stroke-width="2" points="${points}"/><text x="${p}" y="16" font-size="11" fill="#667085">${esc(s.y_label||'')}</text><text x="${w-p}" y="${h-8}" text-anchor="end" font-size="11" fill="#667085">${esc(s.x_label||'')}</text>`})}
$('#refreshTasks').addEventListener('click',()=>loadTasks());if(!window.MCSPageRuntime)setInterval(()=>{if($('#tasks').classList.contains('active')){loadTasks();if(state.selectedTask)showTask(state.selectedTask)}},3000);

function updateSetupAutoCheck(percent,label,detail,phase='running'){
  const root=$('#setupAutoCheckProgress'),bar=$('#setupAutoCheckBar'),pct=$('#setupAutoCheckPercent'),text=$('#setupAutoCheckLabel'),note=$('#setupAutoCheckDetail'),track=root?.querySelector?.('[role="progressbar"]');
  if(!root||!bar||!pct||!text||!note)return;
  const value=Math.max(0,Math.min(100,Number(percent)||0));
  root.dataset.state=phase;
  bar.style.width=`${value}%`;
  pct.textContent=`${Math.round(value)}%`;
  text.textContent=label||'自动浅自检';
  note.textContent=detail||'启动时自动读取安装配置并执行浅检查；深度 Motor-CAD 检查仍由工程师手动触发。';
  if(track)track.setAttribute('aria-valuenow',String(Math.round(value)));
}
function finishSetupAutoCheck(){
  const selected=state.startupInstallation?.selected||null,checks=state.runtimePreflight?.motorcad?.checks||[];
  const fail=checks.some(c=>String(c.status).toUpperCase()==='FAIL');
  const warn=checks.some(c=>['WARNING','WARN'].includes(String(c.status).toUpperCase()));
  state.setupAutoCheckCompleted=true;
  if(!selected)return updateSetupAutoCheck(100,'自动浅自检完成','未检测到已绑定的 Motor-CAD.exe。请完成路径绑定后重新执行浅检查；深度检查不会自动启动。','warning');
  if(fail)return updateSetupAutoCheck(100,'自动浅自检发现阻断项','安装信息已读取，但浅检查存在失败项。请查看右侧检查结果并修复后重试。','error');
  if(warn)return updateSetupAutoCheck(100,'自动浅自检完成，有提示项','基础环境已读取并完成浅检查；存在提示项。首次正式计算前仍建议手动执行 Motor-CAD 深度检查。','warning');
  updateSetupAutoCheck(100,'自动浅自检完成','安装配置和基础运行依赖已自动检查。首次正式计算前仍建议手动执行 Motor-CAD 深度检查。','success');
}

function updateSetupRuntimeState(){
  const el=$('#setupRuntimeState');if(!el)return;const selected=state.startupInstallation?.selected||null;const checks=state.runtimePreflight?.motorcad?.checks||[];const fail=checks.some(c=>String(c.status).toUpperCase()==='FAIL');const warn=checks.some(c=>['WARNING','WARN'].includes(String(c.status).toUpperCase()));
  if(selected&&!selected.exists){el.innerHTML=`<span class="status INVALID">路径失效</span><b>${esc(selected.exe_path||'Motor-CAD.exe')} · 文件不存在，请重新绑定</b>`;return}
  if(selected&&state.runtimePreflight&&!fail&&!warn){el.innerHTML=`<span class="status VALID">已就绪</span><b>${esc(selected.version||'Motor-CAD')} · 环境检查通过</b>`;return}
  if(selected&&state.runtimePreflight&&!fail){el.innerHTML=`<span class="status UNVERIFIED">需确认</span><b>已绑定 ${esc(selected.version||'Motor-CAD')}，检查存在提示项</b>`;return}
  if(selected){el.innerHTML=`<span class="status INFO">已绑定</span><b>${esc(selected.exe_path||'Motor-CAD.exe')} · 建议运行浅检查</b>`;return}
  el.innerHTML='<span class="status UNVERIFIED">待配置</span><b>请先绑定 Motor-CAD.exe，再运行环境检查</b>';
}
async function loadInstallations(){const box=$('#installationList');if(!box)return;try{const r=await api('/api/system/installations');state.startupInstallation=r;const selected=r.selected;if($('#manualMotorcadExe')&&selected?.exe_path)$('#manualMotorcadExe').value=selected.exe_path;const versionNotice=selected&&r.target_version&&!r.selected_version_match?`<div class="issue WARNING"><b>版本需确认</b>：当前绑定 ${esc(selected.version||'未知版本')}，Studio目标映射为 ${esc(r.target_version)}。正式计算前建议完成深度检查和资格校准。</div>`:selected&&r.selected_version_match?`<div class="geometry-pass">✓ 当前 EXE 版本与 Studio 目标映射 ${esc(r.target_version)} 一致。</div>`:'';const entries=(r.installations||[]).map(x=>`<div class="check-item"><span class="check-state ${x.selected?'PASS':'INFO'}">${x.selected?'已绑定':'已发现'}</span><span><b>${esc(x.version||'未知版本')}</b><br><small>${esc(x.exe_path)}</small><br><small>来源：${esc(x.source||'-')}</small></span>${x.selected?'':`<button type="button" data-select-installation="${esc(x.exe_path)}">选择</button>`}</div>`).join('');box.innerHTML=versionNotice+(entries||'<div class="installation-empty"><b>自动扫描未发现 Motor-CAD.exe</b><span>使用“浏览本机…”或粘贴完整EXE路径。手动绑定保存到Studio运行目录，并优先于环境变量。</span></div>');$$('[data-select-installation]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/system/installations/select',{method:'POST',body:JSON.stringify({exe_path:b.dataset.selectInstallation})});state.runtimePreflight=null;await loadInstallations();toast('Motor-CAD EXE已绑定','SUCCESS')}catch(e){toast(e.message,'ERROR')}}));updateSetupRuntimeState();window.loadRuntimeSubmissionReadinessV028?.()}catch(e){box.innerHTML=`<pre class="error-text">${esc(e.message)}</pre>`;updateSetupRuntimeState()}}
async function selectManualMotorcadExe(){const path=$('#manualMotorcadExe')?.value.trim();if(!path)return toast('请输入 Motor-CAD.exe 完整路径','WARNING');const status=$('#manualMotorcadExeStatus');try{const r=await api('/api/system/installations/select',{method:'POST',body:JSON.stringify({exe_path:path})});state.runtimePreflight=null;if(status)status.textContent=`已绑定：${r.exe_path}`;await loadInstallations();toast('Motor-CAD EXE已绑定','SUCCESS')}catch(e){if(status)status.textContent=e.message;toast(e.message,'ERROR')}}
async function browseMotorcadExe(){const status=$('#manualMotorcadExeStatus'),btn=$('#browseMotorcadExe'),old=btn?.textContent;if(btn){btn.disabled=true;btn.textContent='等待选择…'}if(status)status.textContent='正在调起 Windows 原生文件选择器。若未显示，请查看任务栏或 Alt+Tab；选择窗口关闭前此按钮会保持等待状态。';try{const r=await api('/api/system/installations/browse?timeout_s=300',{method:'POST'});if(r.selected){const x=r.installation||{};state.runtimePreflight=null;if($('#manualMotorcadExe'))$('#manualMotorcadExe').value=x.exe_path||'';if(status)status.textContent=`已绑定：${x.exe_path||''}`;await loadInstallations();toast('已通过本机文件选择器绑定 Motor-CAD','SUCCESS')}else if(r.cancelled){if(status)status.textContent='已取消文件选择。'}else{const detail=r.stderr?`；PowerShell：${r.stderr}`:'';if(status)status.textContent=`本机选择器未完成：${r.reason||'unknown'}${detail}`;toast('本机文件选择器未能完成，请查看提示或直接粘贴EXE路径','WARNING',6500)}}catch(e){if(status)status.textContent=`无法打开本机选择器：${e.message}。可直接粘贴 Motor-CAD.exe 完整路径。`;toast(e.message,'WARNING',6500)}finally{if(btn){btn.disabled=false;btn.textContent=old||'浏览本机…'}}}
