async function loadStartupSetup(runShallow=false){
  try{
    if(runShallow)updateSetupAutoCheck(6,'自动浅自检：读取安装配置','正在读取 Motor-CAD 安装发现、手动绑定路径和目标版本。','running');
    await loadInstallations();
    if(runShallow){
      updateSetupAutoCheck(34,'自动浅自检：检查基础运行环境','安装信息已读取，正在检查路径、Python API 与基础依赖；此步骤不会启动 Motor-CAD。','running');
      await loadPreflight(false);
      updateSetupAutoCheck(78,'自动浅自检：读取生产资格状态','基础检查已完成，正在读取 Windows 资格与 Soak 状态。','running');
    }else updateSetupRuntimeState();
    await Promise.all([loadWorkstationAcceptanceStatus(),loadProductionSoakStatus()]);
    if(runShallow)finishSetupAutoCheck();
    else if(state.setupAutoCheckCompleted)finishSetupAutoCheck();
  }catch(error){
    if(runShallow){state.setupAutoCheckCompleted=true;updateSetupAutoCheck(100,'自动浅自检未完成',`自检过程遇到问题：${error?.message||error}。可使用“浅检查”按钮重新执行。`,'error')}
    throw error;
  }
}
