function projectCounts(p){const c=p?.counts||{};return {designs:Number(c.designs ?? ((p?.designs||[]).length||0)),scenarios:Number(c.scenarios ?? ((p?.scenarios||[]).length||0)),experiments:Number(c.experiments ?? ((p?.experiments||[]).length||0)),tasks:Number(c.tasks||0)}}
function renderProjectManager(){const box=$('#projectManagerList');if(!box)return;const source=state.projectManagerRows||[];const q=($('#projectManagerSearch')?.value||'').trim().toLowerCase();const rows=source.filter(p=>!q||String(p.name||'').toLowerCase().includes(q)||String(p.id||'').toLowerCase().includes(q));const totals=source.reduce((a,p)=>{const c=projectCounts(p);a.designs+=c.designs;a.tasks+=c.tasks;return a},{designs:0,tasks:0});const metrics=$('#projectManagerMetrics');if(metrics)metrics.innerHTML=state.projectManagerTrashMode?[['回收站项目',source.length],['可恢复',source.length],['保留设计',totals.designs],['关联任务',totals.tasks]].map(([k,v])=>`<div class="metric-card"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join(''):[['项目总数',source.length],['当前项目',activeProjectRecord()?.name||'未进入'],['设计总数',totals.designs],['关联任务',totals.tasks]].map(([k,v])=>`<div class="metric-card"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');box.innerHTML=rows.length?rows.map(p=>{const c=projectCounts(p),active=p.id===state.activeProjectId;return `<article class="project-card ${active?'active-project':''}"><div class="project-card-head"><div><span class="eyebrow">${active?uiText('当前项目','ACTIVE PROJECT'):(state.projectManagerTrashMode?uiText('回收站','TRASHED'):'PROJECT')}</span><h3>${esc(p.name)}</h3><small>${esc(p.id)}</small></div>${active?'<span class="status VALID">已进入</span>':''}</div><p>${esc(p.description||uiText('暂无项目说明','No description'))}</p><div class="project-card-stats"><span><b>${c.designs}</b> Designs</span><span><b>${c.scenarios}</b> Scenarios</span><span><b>${c.tasks}</b> Tasks</span></div><div class="project-card-foot"><small>${uiText('更新','Updated')} ${esc(formatDate(p.updated_at)||'-')}</small><div class="actions">${state.projectManagerTrashMode?`<button type="button" class="primary" data-project-restore="${esc(p.id)}">恢复项目</button>`:`<button type="button" data-project-edit="${esc(p.id)}">基本信息</button><button type="button" class="primary" data-project-enter="${esc(p.id)}">${active?'返回项目':'进入项目'}</button>`}</div></div></article>`}).join(''):`<div class="workspace-empty compact"><b>${state.projectManagerTrashMode?'回收站为空':'没有匹配项目'}</b><span>${state.projectManagerTrashMode?'删除的项目会先进入这里，工程历史保持可恢复。':'可在左侧新建项目，或调整搜索条件。'}</span></div>`;
  $$('[data-project-enter]').forEach(b=>b.addEventListener('click',()=>enterProject(b.dataset.projectEnter)));$$('[data-project-edit]').forEach(b=>b.addEventListener('click',()=>openProjectEditor(b.dataset.projectEdit)));$$('[data-project-restore]').forEach(b=>b.addEventListener('click',()=>restoreProjectFromTrash(b.dataset.projectRestore)));
}
