async function trashProjectFromManager(id){const p=(state.projectManagerRows||[]).find(x=>x.id===id);if(!p)return;const c=projectCounts(p);if(!window.StudioDialog)return toast('页内确认组件尚未加载，请稍后重试。','WARNING');const ok=await StudioDialog.confirm({title:'将项目移入回收站？',html:`<p><b>${esc(p.name)}</b> 将从项目列表隐藏。</p><p>${c.designs} 个 Design、${c.scenarios} 个 Scenario、${c.tasks} 个 Task 的工程血缘会继续保留，可从回收站恢复。</p>`,confirmText:'移入回收站',danger:true});if(!ok)return;try{await api(`/api/projects/${encodeURIComponent(id)}`,{method:'DELETE'});if(state.activeProjectId===id)setActiveProject(null);state.projectManagerEditorId=null;$('#projectEditorPanel')?.classList.add('hidden');$('.project-manager-layout')?.classList.remove('editor-open');await loadProjectManager();toast('项目已移入回收站','SUCCESS')}catch(e){toast(e.message,'ERROR')}}
