$('#projectManagerTrash')?.addEventListener('click',()=>showProjectTrash(null,null));$('#projectManagerSearch')?.addEventListener('input',renderProjectManager);$('#projectCreate')?.addEventListener('click',async()=>{const name=$('#projectCreateName')?.value.trim(),description=$('#projectCreateDescription')?.value||'',status=$('#projectCreateStatus');if(!name)return toast('请输入项目名称','WARNING');try{if(status)status.textContent='正在创建项目…';const p=await api('/api/projects',{method:'POST',body:JSON.stringify({name,description})});if($('#projectCreateName'))$('#projectCreateName').value='';if($('#projectCreateDescription'))$('#projectCreateDescription').value='';state.workspaceProjects=await api('/api/projects');state.projectManagerRows=state.workspaceProjects;if(status)status.textContent=`已创建 ${p.id}`;await enterProject(p.id)}catch(e){if(status)status.textContent=e.message;toast(e.message,'ERROR')}});$('#projectEditorSave')?.addEventListener('click',saveProjectEditor);$('#projectEditorDelete')?.addEventListener('click',()=>trashProjectFromManager(state.projectManagerEditorId));$('#projectEditorClose')?.addEventListener('click',()=>{state.projectManagerEditorId=null;$('#projectEditorPanel')?.classList.add('hidden');$('.project-manager-layout')?.classList.remove('editor-open')});

