async function loadWorkspace(routeCtx=null){if(!state.activeProjectId){showTab('projects');return}try{const options=routeCtx?.signal?{signal:routeCtx.signal}:{};const projects=await api('/api/projects',options);if(routeCtx&&!window.MCSPageRuntime?.isContextActive?.(routeCtx))return;state.workspaceProjects=projects;if(!state.workspaceProjects.some(p=>p.id===state.activeProjectId)){setActiveProject(null);showTab('projects');return}await openWorkspaceProject(state.activeProjectId,routeCtx)}catch(e){if(window.MCSPageRuntime?.isAbortError?.(e))return;const message=e?.message||humanApiDetail(e?.detail)||'项目数据未能加载，请刷新一次；若仍失败，请在问题中心按当前请求定位。';toast(`项目工作区加载失败：${message}`,'ERROR')}}
