async function useWorkspaceRevisionAsTask(){
  const rev=state.workspaceRevision,d=state.workspaceDesign;if(!rev||!d)return toast('请选择Design Revision','WARNING');const t=state.templates.find(x=>x.id===d.template_id);if(!t)return toast('对应模板未加载','ERROR');
  setActiveProject(state.workspaceProject?.id||state.activeProjectId);
  window.MCSEngineeringContext?.setMotorRevision?.(rev,{solution:d,source:'app:workspace-to-analysis'});
  // Legacy task hydration remains a compatibility projection for modules not yet migrated.
  // Older code rendered template defaults first, overwrote the inputs afterwards and
  // forgot to re-render the preview, so the initial schematic stayed at the template
  // geometry until the operator touched any field.  Register the already loaded
  // revision and delegate to workflow.js, which hydrates inputs/materials/base revision
  // and renders the preview from the effective revision snapshot in one transaction.
  state.projectRevisionIndex=state.projectRevisionIndex||new Map();
  state.projectRevisionIndex.set(rev.id,{design:d,revision:rev});
  if(typeof applyTaskDesignRevision==='function'){
    await applyTaskDesignRevision(rev.id,{silent:true});
  }else{
    state.taskDesignRevisionId=rev.id;state.taskBaseRevision=rev;state.selectedTemplate=t;renderTemplateSelect();if($('#templateSelect'))$('#templateSelect').value=t.id;await onTemplateChange();
    Object.entries(rev.parameters||{}).forEach(([k,v])=>{const input=document.querySelector(`[data-param="${CSS.escape(k)}"]`);if(input)input.value=v});
    if(typeof applyMaterialRevision==='function')applyMaterialRevision(rev.materials||{});
    renderLiveDesignPreview();updateTaskPreview();
  }
  syncProjectContextSelectors();if($('#taskName'))$('#taskName').value=`${d.name} Rev.${rev.revision}`;
  window.MCSModelGate?.invalidate?.('已载入 Design Revision 参数快照');
  const route=state.activeProjectId?`/app/projects/${encodeURIComponent(state.activeProjectId)}/simulation/analyses`:null;
  if(route&&window.MCSRouter?.navigate)MCSRouter.navigate(route);else showTab('analysisConfig');
  toast('已将当前 Design Revision 设为分析配置上下文','SUCCESS');
}
