async function loadTaskTimeline(routeCtx=null){
  if(!state.monitorTask)return;try{const data=await api(`/api/tasks/${state.monitorTask}/timeline?limit=1500`,routeCtx?.signal?{signal:routeCtx.signal}:{});if(routeCtx&&!window.MCSPageRuntime?.isContextActive?.(routeCtx))return;renderTaskTimeline(data)}catch(e){if(window.MCSPageRuntime?.isAbortError?.(e))return;if($('#stagePerformanceTable'))$('#stagePerformanceTable').innerHTML=`<pre class="error-text">${esc(e.message)}</pre>`}
}
function renderTaskTimeline(data){
  const perfRows=(data?.stage_performance||[]).slice().sort((a,b)=>(b.mean_s||0)-(a.mean_s||0));
  if($('#stagePerformanceTable'))$('#stagePerformanceTable').innerHTML=perfRows.length?`<table class="data-table compact"><thead><tr><th>Stage</th><th>Samples</th><th>Avg</th><th>Median</th><th>P95</th><th>Max</th></tr></thead><tbody>${perfRows.map(v=>`<tr><td><b>${esc(v.stage)}</b></td><td>${esc(v.count)}</td><td>${formatDuration(v.mean_s)}</td><td>${formatDuration(v.median_s)}</td><td>${formatDuration(v.p95_s)}</td><td>${formatDuration(v.max_s)}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">尚无已完成Stage耗时。</p>';
  const waits=data?.waiting_cases||[];if($('#waitingCaseTable'))$('#waitingCaseTable').innerHTML=waits.length?`<table class="data-table compact"><thead><tr><th>Case</th><th>State</th><th>Reason</th><th>Last event</th></tr></thead><tbody>${waits.map(w=>`<tr><td><button type="button" class="link-button" data-wait-case="${esc(w.case_id)}">${esc(w.case_id)}</button></td><td>${esc(w.status||'-')}</td><td><span class="wait-reason">${esc(w.wait_reason||'QUEUED')}</span></td><td>${esc(w.last_message||'-')}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">当前没有等待中的Case。</p>';
  $$('[data-wait-case]').forEach(b=>b.addEventListener('click',()=>{const taskId=state.monitorTask;if(!taskId)return;state.selectedTask=taskId;if(window.MCSRouter?.navigate)MCSRouter.navigate(`/app/projects/${encodeURIComponent(state.activeProjectId)}/simulation/tasks/${encodeURIComponent(taskId)}`);else{showTab('tasks');showTask(taskId)}}));
}
