function logQueryString(){const p=new URLSearchParams();const level=$('#logLevel')?.value,component=$('#logComponent')?.value,task=$('#logTaskFilter')?.value.trim(),caseId=$('#logCaseFilter')?.value.trim(),stage=$('#logStageFilter')?.value.trim(),q=$('#logSearch')?.value.trim();if(level)p.set('level',level);if(component)p.set('component',component);if(task)p.set('task_id',task);if(caseId)p.set('case_id',caseId);if(stage)p.set('stage',stage);if(q)p.set('q',q);if($('#logCurrentSession')?.checked)p.set('current_session','true');p.set('limit','1000');return p.toString()}
async function loadLogs(routeCtx=null){
  try{
    const options=routeCtx?.signal?{signal:routeCtx.signal}:{},current=$('#logCurrentSession')?.checked?'&current_session=true':'',task=$('#logTaskFilter')?.value.trim(),diagTask=task?`&task_id=${encodeURIComponent(task)}`:'';const [summary,diagnostics,rows]=await Promise.all([api('/api/logs/summary?minutes=60'+current,options),api('/api/logs/diagnostics?minutes=240&limit=30'+current+diagTask,options),api('/api/logs?'+logQueryString(),options)]);if(routeCtx&&!window.MCSPageRuntime?.isContextActive?.(routeCtx))return;state.logSummary=summary;state.logDiagnostics=diagnostics;state.logs=rows||[];state.lastLogSeq=Math.max(state.lastLogSeq,...state.logs.map(r=>Number(r.seq)||0),Number(summary.last_seq)||0);renderLogMetrics();renderProblems();renderStructuredLogs();renderLogComponentFilter();updateDiagnosticDownload();connectLogStream();
  }catch(e){if(window.MCSPageRuntime?.isAbortError?.(e))return;toast(`日志加载失败：${e.message}`,'ERROR')}
}
function renderLogMetrics(){const s=state.logSummary;if(!s||!$('#logMetrics'))return;$('#logMetrics').innerHTML=[['可观测性健康度',`${s.health_score}/100`],['最近60分钟',s.total],['警告',s.warnings],['错误',s.errors],['组件',Object.keys(s.components||{}).length],['日志序号',s.last_seq]].map(([k,v])=>`<div class="metric-card"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}
function renderLogComponentFilter(){const sel=$('#logComponent');if(!sel||!state.logSummary)return;const old=sel.value;sel.innerHTML='<option value="">全部组件</option>'+Object.keys(state.logSummary.components||{}).map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');if([...sel.options].some(o=>o.value===old))sel.value=old}
function renderProblems(){const d=state.logDiagnostics,box=$('#problemCenter');if(!box)return;const problems=d?.problems||[];box.innerHTML=problems.length?problems.map(p=>{const last=p.last||{},role=p.root_cause?'根因':p.consequence?'后果':'异常';return `<article class="problem-card ${esc(p.level||'WARNING')}"><div class="problem-head"><span class="problem-severity">${esc(p.level||'WARNING')}</span><span class="badge ${p.root_cause?'error':p.consequence?'':'warn'}">${esc(role)} · ${esc(p.category||'GENERAL')}</span><b>${esc(p.signature)}</b><span>× ${esc(p.count)} · score ${esc(p.problem_score??'-')}</span></div><p>${esc(last.message||'')}</p><div class="problem-links">${last.task_id?`<button type="button" class="link-button" data-log-task="${esc(last.task_id)}">${esc(last.task_id)}</button>`:''}${last.case_id?`<button type="button" class="link-button case" data-log-case="${esc(last.case_id)}" data-log-task="${esc(last.task_id||'')}">${esc(last.case_id)}</button>`:''}<span>${esc(last.component||'')}</span><span>${esc(last.stage||'')}</span></div><ul>${(p.recommendations||[]).map(r=>`<li>${esc(r)}</li>`).join('')}</ul></article>`}).join(''):'<div class="problem-empty"><b>未发现聚合异常</b><span>最近4小时没有WARNING以上的问题签名。</span></div>';bindLogReferences()}
function renderStructuredLogs(){const box=$('#structuredLogTable');if(!box)return;const rows=(state.logs||[]).slice(0,1000);box.innerHTML=rows.length?`<table class="data-table log-table"><thead><tr><th>Time</th><th>Level</th><th>Component</th><th>Event / Stage</th><th>Task / Case</th><th>Message</th><th>PID</th><th>Trace</th></tr></thead><tbody>${rows.map(r=>`<tr class="log-row ${esc(r.level||'INFO')}"><td>${esc(r.timestamp?new Date(r.timestamp).toLocaleTimeString():'-')}</td><td><span class="log-level ${esc(r.level||'INFO')}">${esc(r.level||'INFO')}</span></td><td>${esc(r.component||'-')}</td><td><b>${esc(r.event_type||'-')}</b><small>${esc(r.stage||'')}</small></td><td>${r.task_id?`<button type="button" class="link-button" data-log-task="${esc(r.task_id)}">${esc(r.task_id)}</button>`:'-'}${r.case_id?`<button type="button" class="link-button case" data-log-case="${esc(r.case_id)}" data-log-task="${esc(r.task_id||'')}">${esc(r.case_id)}</button>`:''}</td><td class="log-message">${esc(r.message||'')}<details><summary>payload</summary><pre>${esc(JSON.stringify(r.payload||{},null,2))}</pre></details></td><td>${esc(r.pid||'-')}</td><td><code>${esc(r.request_id||r.trace_id||'-')}</code></td></tr>`).join('')}</tbody></table>`:'<div class="problem-empty"><b>没有匹配日志</b><span>调整级别、组件、Task/Case或关键词过滤器。</span></div>';bindLogReferences()}
function bindLogReferences(){$$('[data-log-task]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.logTask;if(!id)return;window.MCSEngineeringContext?.setExecution?.(id,{taskId:id,kind:'task',source:'app:log-task'});if(!window.MCSEngineeringContext)state.selectedTask=id;if(window.MCSRouter?.navigate)MCSRouter.navigate(`/app/projects/${encodeURIComponent(state.activeProjectId)}/simulation/tasks/${encodeURIComponent(id)}`);else{showTab('tasks');showTask(id)}}));$$('[data-log-case]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.logTask;if(!id)return;window.MCSEngineeringContext?.setExecution?.(id,{taskId:id,kind:'task',source:'app:log-monitor'});if(!window.MCSEngineeringContext)state.monitorTask=id;if(window.MCSRouter?.navigate)MCSRouter.navigate(`/app/projects/${encodeURIComponent(state.activeProjectId)}/simulation/monitor/${encodeURIComponent(id)}`);else{showTab('monitor');$('#monitorTaskSelect').value=id;openMonitorTask(id)}}))}
function updateDiagnosticDownload(){const a=$('#downloadDiagnostics');if(!a)return;const task=$('#logTaskFilter')?.value.trim(),current=$('#logCurrentSession')?.checked?'&current_session=true':'';a.dataset.exportUrl=`/api/logs/export.zip?minutes=240${task?`&task_id=${encodeURIComponent(task)}`:''}${current}`}
async function downloadDiagnosticBundle(e){e?.preventDefault();const a=$('#downloadDiagnostics');if(!a)return;const old=a.textContent;a.disabled=true;a.textContent=uiText('正在打包…','Packaging…');try{const url=a.dataset.exportUrl||'/api/logs/export.zip?minutes=240';const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(await r.text());const blob=await r.blob();const cd=r.headers.get('content-disposition')||'';const m=cd.match(/filename="?([^";]+)"?/i);const name=m?m[1]:`motorcad-diagnostics-${Date.now()}.zip`;const blobUrl=URL.createObjectURL(blob);const link=document.createElement('a');link.href=blobUrl;link.download=name;document.body.appendChild(link);link.click();link.remove();requestAnimationFrame(()=>URL.revokeObjectURL(blobUrl));toast(uiText('诊断日志包已导出','Diagnostics bundle exported'),'SUCCESS')}catch(err){toast(err.message,'ERROR')}finally{a.disabled=false;a.textContent=old}}
$('#downloadDiagnostics')?.addEventListener('click',downloadDiagnosticBundle)
function connectLogStream(){if(state.logStream)return;const badge=$('#logConnection');try{const es=new EventSource(`/api/logs/stream?after_seq=${state.lastLogSeq||0}`);state.logStream=es;if(badge){badge.textContent='实时连接中';badge.className='badge connection-pulse'}es.addEventListener('runtime_log',e=>{try{const row=JSON.parse(e.data);state.lastLogSeq=Math.max(state.lastLogSeq,Number(row.seq)||0);if($('#logAutoRefresh')?.checked){state.logs.unshift(row);if(state.logs.length>1000)state.logs.length=1000;renderStructuredLogs();if(['WARNING','ERROR','CRITICAL'].includes(row.level)){if(row.level!=='WARNING')toast(`${row.component} · ${row.message}`,row.level,7000);debouncedDiagnosticRefresh()}}}catch{}});es.onopen=()=>{if(badge){badge.textContent='实时已连接';badge.className='badge ok'}};es.onerror=()=>{if(badge){badge.textContent='实时重连中';badge.className='badge warn connection-pulse'}}}catch{if(badge){badge.textContent='实时不可用';badge.className='badge error'}}}
let logDebounce=null;function debouncedLogReload(){clearTimeout(logDebounce);logDebounce=setTimeout(loadLogs,300)}let diagDebounce=null;function debouncedDiagnosticRefresh(){clearTimeout(diagDebounce);diagDebounce=setTimeout(async()=>{try{const current=$('#logCurrentSession')?.checked?'&current_session=true':'',task=$('#logTaskFilter')?.value.trim(),diagTask=task?`&task_id=${encodeURIComponent(task)}`:'';state.logDiagnostics=await api('/api/logs/diagnostics?minutes=240&limit=30'+current+diagTask);state.logSummary=await api('/api/logs/summary?minutes=60'+current);renderProblems();renderLogMetrics()}catch{}},900)}
$('#refreshLogs')?.addEventListener('click',()=>loadLogs());$('#logCurrentSession')?.addEventListener('change',()=>loadLogs());['logLevel','logComponent'].forEach(id=>$(`#${id}`)?.addEventListener('change',debouncedLogReload));['logTaskFilter','logCaseFilter','logStageFilter','logSearch'].forEach(id=>$(`#${id}`)?.addEventListener('input',()=>{updateDiagnosticDownload();debouncedLogReload()}));

// ---- V0.11 Operator UX, materials, live schematic and result viewer --------------
const uiText=(zh,en)=>state.language==='en'?(en||zh):zh;

function stopSystemPolling(){if(state.systemPollTimer){clearInterval(state.systemPollTimer);state.systemPollTimer=null}}
async function pollSystemSnapshot(){try{renderSystemSnapshot(await api('/api/system/metrics'));const badge=$('#liveBadge');if(badge){badge.textContent=uiText('实时通道已切换轮询','Live channel · polling fallback');badge.className='badge warn'}}catch(e){const badge=$('#liveBadge');if(badge){badge.textContent=uiText('状态获取失败','Status unavailable');badge.className='badge error'}}}
function startSystemPolling(){stopSystemPolling();pollSystemSnapshot();state.systemPollTimer=setInterval(pollSystemSnapshot,5000)}
connectSystemStream=function(){
  stopSystemPolling();if(state.systemStream){try{state.systemStream.close()}catch{}state.systemStream=null}
  const badge=$('#liveBadge');state.systemStreamFailures=0;
  try{
    const es=new EventSource('/api/system/stream');state.systemStream=es;
    if(badge){badge.textContent=uiText('实时通道连接中','Connecting live channel');badge.className='badge connection-pulse';badge.title=uiText('点击可手动重新连接','Click to reconnect')}
    es.addEventListener('system_snapshot',e=>{try{renderSystemSnapshot(JSON.parse(e.data));state.systemStreamFailures=0;if(badge){badge.textContent=uiText('实时通道已连接','Live connected');badge.className='badge ok'}}catch{}});
    es.addEventListener('system_error',e=>{state.systemStreamFailures+=1;let msg='';try{msg=JSON.parse(e.data)?.message||''}catch{}if(badge){badge.textContent=uiText('实时服务降级','Live service degraded');badge.className='badge warn';badge.title=msg||badge.title}});
    es.onopen=()=>{state.systemStreamFailures=0;stopSystemPolling();if(badge){badge.textContent=uiText('实时通道已连接','Live connected');badge.className='badge ok'}};
    es.onerror=()=>{state.systemStreamFailures+=1;if(state.systemStreamFailures>=3){try{es.close()}catch{}state.systemStream=null;startSystemPolling();toast(uiText('实时推送连续失败，已自动切换到5秒轮询；点击状态徽标可重试SSE。','Live push failed repeatedly; switched to 5-second polling. Click the badge to retry SSE.'),'WARNING',6500)}else if(badge){badge.textContent=uiText(`实时重连中 (${state.systemStreamFailures}/3)`,`Reconnecting (${state.systemStreamFailures}/3)`);badge.className='badge warn connection-pulse'}};
  }catch(e){startSystemPolling();if(badge){badge.textContent=uiText('实时通道不可用，使用轮询','Live unavailable · polling');badge.className='badge warn'}}
};

function currentDesignParameters(){const values={...(state.selectedTemplate?.defaults||{})};$$('[data-param]').forEach(input=>{const n=Number(input.value);values[input.dataset.param]=Number.isFinite(n)?n:input.value});return values}
function schematicNumber(params,key,fallback){const n=Number(params?.[key]);return Number.isFinite(n)?n:Number(fallback)||0}
function motorCadStyleSchematic(t,large=false,params={}){
  const axial=Boolean(t?.is_axial),top=String(t?.topology||t?.motor_type||'').toUpperCase();
  const poles=Math.max(2,Math.min(40,Math.round(schematicNumber(params,'pole_count',t?.poles||8))));
  const slots=Math.max(3,Math.min(60,Math.round(schematicNumber(params,'slot_count',t?.slots||12))));
  const od=Math.max(20,schematicNumber(params,'stator_outer_diameter',t?.defaults?.stator_outer_diameter||t?.stator_outer_diameter||200));
  const id=Math.max(5,Math.min(od*.9,schematicNumber(params,'stator_inner_diameter',t?.defaults?.stator_inner_diameter||od*.6)));
  const gap=Math.max(.05,schematicNumber(params,'air_gap',t?.defaults?.air_gap||t?.airgap||1));
  const mag=Math.max(.2,schematicNumber(params,'magnet_thickness',t?.defaults?.magnet_thickness||5));
  const tooth=Math.max(1,schematicNumber(params,'tooth_width',t?.defaults?.tooth_width||6));
  if(axial){
    const scale=1.15;const center=120;const statorH=Math.max(22,Math.min(42,schematicNumber(params,'stator_lamination_length',t?.defaults?.stator_lamination_length||35)*.65));const gapH=Math.max(4,Math.min(15,gap*4));const magH=Math.max(7,Math.min(24,mag*.55));const rotorH=16;
    const total=rotorH+magH+gapH+statorH+gapH+magH+rotorH;let y=30+(150-total)/2;let magnetsTop='',magnetsBottom='';const shown=Math.min(14,poles);const usable=166,w=usable/shown*.72,step=usable/shown;
    for(let i=0;i<shown;i++){const x=37+i*step;const cls=i%2?'magnet-s':'magnet-n';magnetsTop+=`<rect x="${x.toFixed(1)}" y="${(y+rotorH).toFixed(1)}" width="${w.toFixed(1)}" height="${magH.toFixed(1)}" rx="2" class="${cls}"/>`;magnetsBottom+=`<rect x="${x.toFixed(1)}" y="${(y+rotorH+magH+gapH+statorH+gapH).toFixed(1)}" width="${w.toFixed(1)}" height="${magH.toFixed(1)}" rx="2" class="${cls}"/>`}
    return `<div class="template-schematic motorcad-style ${large?'large':''}"><svg viewBox="0 0 240 190" role="img" aria-label="${esc(uiText('轴向磁通电机参数化示意','Parametric axial-flux motor schematic'))}"><defs><linearGradient id="steelA" x1="0" x2="1"><stop offset="0" stop-color="#485f7a"/><stop offset=".5" stop-color="#7b8da3"/><stop offset="1" stop-color="#485f7a"/></linearGradient><pattern id="lamA" width="5" height="5" patternUnits="userSpaceOnUse"><rect width="5" height="5" fill="#9baabd"/><path d="M0 1H5" stroke="#62758e" stroke-width=".7"/></pattern></defs><text x="120" y="16" text-anchor="middle" class="schematic-title">AFPM · ${esc(top)}</text><rect x="27" y="${y.toFixed(1)}" width="186" height="${rotorH}" rx="3" fill="url(#steelA)" class="steel-outline"/>${magnetsTop}<rect x="31" y="${(y+rotorH+magH).toFixed(1)}" width="178" height="${gapH}" rx="2" class="airgap"/><rect x="34" y="${(y+rotorH+magH+gapH).toFixed(1)}" width="172" height="${statorH}" rx="4" fill="url(#lamA)" class="steel-outline"/><text x="120" y="${(y+rotorH+magH+gapH+statorH/2+4).toFixed(1)}" text-anchor="middle" class="part-label">STATOR</text><rect x="31" y="${(y+rotorH+magH+gapH+statorH).toFixed(1)}" width="178" height="${gapH}" rx="2" class="airgap"/>${magnetsBottom}<rect x="27" y="${(y+rotorH+magH+gapH+statorH+gapH+magH).toFixed(1)}" width="186" height="${rotorH}" rx="3" fill="url(#steelA)" class="steel-outline"/><text x="12" y="${(y+rotorH+magH+gapH+statorH/2+3).toFixed(1)}" class="dimension-label">Ø${od.toFixed(1)}</text><text x="226" y="${(y+rotorH+magH+gapH-2).toFixed(1)}" text-anchor="end" class="dimension-label">g=${gap.toFixed(2)} mm</text></svg></div>`;
  }
  const cx=120,cy=95;const outerR=70,statorInnerR=outerR*(id/od),gapVis=Math.max(2.2,Math.min(8,gap*2.8));const rotorR=Math.max(16,statorInnerR-gapVis);const magVis=Math.max(4,Math.min(13,mag*.55));let slotsSvg='',mags='';
  for(let i=0;i<slots;i++){const a=i*2*Math.PI/slots-Math.PI/2;const r1=statorInnerR+2,r2=outerR-4;const half=Math.max(.012,Math.min(.05,tooth/od*.9));const p1=[cx+r1*Math.cos(a-half),cy+r1*Math.sin(a-half)],p2=[cx+r2*Math.cos(a-half),cy+r2*Math.sin(a-half)],p3=[cx+r2*Math.cos(a+half),cy+r2*Math.sin(a+half)],p4=[cx+r1*Math.cos(a+half),cy+r1*Math.sin(a+half)];slotsSvg+=`<path d="M${p1[0].toFixed(1)},${p1[1].toFixed(1)} L${p2[0].toFixed(1)},${p2[1].toFixed(1)} L${p3[0].toFixed(1)},${p3[1].toFixed(1)} L${p4[0].toFixed(1)},${p4[1].toFixed(1)} Z" class="slot-cut"/>`}
  for(let i=0;i<poles;i++){const a0=i*2*Math.PI/poles-Math.PI/2-Math.PI/poles*.75,a1=i*2*Math.PI/poles-Math.PI/2+Math.PI/poles*.75;const ro=rotorR-1,ri=Math.max(8,ro-magVis);const pts=[[cx+ri*Math.cos(a0),cy+ri*Math.sin(a0)],[cx+ro*Math.cos(a0),cy+ro*Math.sin(a0)],[cx+ro*Math.cos(a1),cy+ro*Math.sin(a1)],[cx+ri*Math.cos(a1),cy+ri*Math.sin(a1)]];mags+=`<path d="M${pts.map(p=>p.map(v=>v.toFixed(1)).join(',')).join(' L')} Z" class="${i%2?'magnet-s':'magnet-n'}"/>`}
  return `<div class="template-schematic motorcad-style ${large?'large':''}"><svg viewBox="0 0 240 190" role="img" aria-label="${esc(uiText('径向磁通电机参数化示意','Parametric radial-flux motor schematic'))}"><defs><radialGradient id="rotorR"><stop offset="0" stop-color="#6c7e94"/><stop offset="1" stop-color="#41566f"/></radialGradient></defs><text x="120" y="15" text-anchor="middle" class="schematic-title">RFPM · ${esc(top)}</text><circle cx="${cx}" cy="${cy}" r="${outerR}" class="stator-steel"/><circle cx="${cx}" cy="${cy}" r="${statorInnerR.toFixed(1)}" class="bore"/>${slotsSvg}<circle cx="${cx}" cy="${cy}" r="${(rotorR+gapVis*.35).toFixed(1)}" class="airgap-ring"/><circle cx="${cx}" cy="${cy}" r="${rotorR.toFixed(1)}" fill="url(#rotorR)" class="steel-outline"/>${mags}<circle cx="${cx}" cy="${cy}" r="${Math.max(8,rotorR*.28).toFixed(1)}" class="shaft"/><text x="8" y="177" class="dimension-label">OD ${od.toFixed(1)} mm · ID ${id.toFixed(1)} mm</text><text x="232" y="177" text-anchor="end" class="dimension-label">g ${gap.toFixed(2)} mm</text></svg></div>`;
}
motorSchematic=function(t,large=false,params=null){return motorCadStyleSchematic(t,large,params||t?.defaults||{})};
function renderLiveDesignPreview(){const box=$('#liveDesignPreview');if(!box||!state.selectedTemplate)return;const params=currentDesignParameters();box.innerHTML=motorSchematic(state.selectedTemplate,true,params);const dims=$('#liveDesignDimensions');if(dims){const keys=['pole_count','slot_count','stator_outer_diameter','stator_inner_diameter','air_gap','magnet_thickness'];dims.innerHTML=keys.filter(k=>params[k]!==undefined).map(k=>`<span><b>${esc(state.registry?.parameters?.[k]?.label||k)}</b> ${esc(params[k])}${state.registry?.parameters?.[k]?.unit?' '+esc(state.registry.parameters[k].unit):''}</span>`).join('')}}

function parameterHelpText(id,d){const effects={air_gap:'影响气隙磁密、转矩、功率因数与制造公差；过小会增加装配和偏心风险。',magnet_thickness:'影响永磁体磁势、磁体用量和退磁裕度；应结合工作温度与磁钢牌号评估。',magnet_arc:'影响磁密波形、反电动势谐波与转矩脉动。',pole_count:'决定电频率及磁极节距，会联动铁耗、绕组与机械设计。',slot_count:'与极数共同决定绕组方案、齿槽转矩及谐波特征。',turns_per_coil:'影响反电动势、电流需求与铜耗。',peak_current_a:'运行工况参数，直接影响转矩、铜耗与温升。',shaft_speed_rpm:'运行转速，影响电频率、铁耗、反电动势和机械约束。'};return effects[id]||d.description||'该参数属于平台标准化工程参数。修改后会写入对应Motor-CAD Automation变量，并在真实求解时执行回读核对。'}
renderParameterGroups=function(){
  const host=$('#parameterGroups'),t=state.selectedTemplate;if(!host||!t||!state.registry)return;const schema=state.registry.parameters;const categoryLabels={topology:'拓扑',geometry:'主要几何',magnet:'永磁体',winding:'绕组',operating:'运行工况',environment:'环境',cooling:'冷却'};const groups={};
  (t.parameter_ids||[]).forEach(id=>{const d=schema[id];if(!d)return;if(state.parameterLevel==='basic'&&d.level!=='basic')return;(groups[d.category]??=[]).push([id,d])});
  host.innerHTML=Object.entries(groups).map(([cat,items])=>`<section class="parameter-group" data-param-group="${esc(cat)}"><div class="parameter-group-title"><h3>${esc(categoryLabels[cat]||cat)}</h3><span>${items.length}${uiText('项','')}</span></div><div class="property-editor">${items.map(([id,d])=>{const value=t.defaults?.[id]??d.default??'';const meta=t.default_metadata?.[id]||{};const variable=(d.motorcad_candidates||[])[0]||'-';const interaction=t.interaction_notes?.[id]||'';const label=state.language==='en'?(d.label_en||d.label||id):(d.label_en?`${d.label} / ${d.label_en}`:(d.label||id));return `<div class="parameter-field" data-param-field="${esc(id)}" data-default="${esc(value)}" data-search="${esc([id,d.label,d.label_en,variable,d.description||'',interaction].join(' ').toLowerCase())}"><div class="parameter-label"><b>${esc(label)}</b><button type="button" class="param-help" title="${esc(parameterHelpText(id,d))}" aria-label="${esc(d.label||id)}说明">?</button><small>${esc(d.unit||'')}</small></div><div class="parameter-control"><input data-param="${esc(id)}" type="number" step="${d.type==='integer'?'1':'any'}" min="${d.minimum??''}" max="${d.maximum??''}" value="${esc(value)}"><span class="unit-suffix">${esc(d.unit||'')}</span></div><div class="parameter-meta"><span>${meta.verified?uiText('✓ 已实机验证','✓ Runtime verified'):uiText('○ 待实机回读','○ Runtime verification pending')}</span><span>${uiText('模板','Template')} ${esc(value)} ${esc(d.unit||'')}</span>${interaction?`<span class="parameter-coupling-note" title="${esc(interaction)}">⚠ ${esc(interaction)}</span>`:''}<details><summary>${uiText('技术映射','Technical mapping')}</summary><code>${esc(id)}</code><br><code>${esc(variable)}</code><br>${esc(d.motorcad_context||'-')}</details></div></div>`}).join('')}</div></section>`).join('');
  const ambientTemp=$('#ambientTemp');if(ambientTemp)ambientTemp.value=t.defaults?.ambient_temperature_c??25;updateParameterInspector();renderLiveDesignPreview();
  $$('.param-help').forEach(b=>b.addEventListener('click',()=>toast(b.title,'INFO',9000)));
};
const _updateParameterInspectorV011=updateParameterInspector;updateParameterInspector=function(){_updateParameterInspectorV011();if($('#parameterChangeSummary')){const n=$$('[data-param-field].changed').length;$('#parameterChangeSummary').textContent=uiText(`${n}项修改`,`${n} changed`)}};

function contextChinese(context){return ({EMag:'电磁分析',Therm:'热分析',Lab:'性能图谱 / Motor-CAD Lab',Mechanical:'机械与NVH',Global:'全局'})[context]||context}
function expertDescription(entry){const meta=entry.metadata||{};if(meta.description_zh)return state.language==='en'?(meta.description_en||meta.description_zh):meta.description_zh;const n=String(entry.automation_name||'').toLowerCase(),raw=entry.description||'';const rules=[[/mesh|element|fea/i,'网格/有限元离散设置。通常沿用模板默认值，只有进行网格收敛研究时才调整。'],[/torque.*point|points.*cycle/i,'每个电周期用于转矩计算的采样点数；增大通常提高波形分辨率，同时增加计算时间。'],[/back.*emf/i,'反电动势相关计算或输出控制。'],[/cogging/i,'齿槽转矩计算设置。'],[/demag/i,'永磁体退磁分析相关设置。'],[/induct/i,'电感或Ld/Lq相关计算设置。'],[/short.*circuit/i,'短路工况计算设置。'],[/force/i,'电磁力/力谐波分析设置，可用于NVH后处理。'],[/flow|fluid/i,'流体或冷却回路相关Automation参数。'],[/temperature|temp/i,'温度、初始条件或热边界相关参数。'],[/magnet/i,'永磁体几何、材料或计算控制相关参数。'],[/speed|rpm/i,'转速或速度相关参数。'],[/current/i,'电流、激励或控制工况相关参数。'],[/voltage/i,'电压、电源或限制条件相关参数。']];for(const [re,zh] of rules)if(re.test(n))return zh;return raw?`Motor-CAD说明：${raw}`:'Motor-CAD原生Automation参数。仅在明确知道其物理意义或依据官方文档/已验证模板时修改。'}
renderExpertParameters=function(){
  const box=$('#expertParamFields');if(!box)return;const q=($('#expertSearch')?.value||'').trim().toLowerCase();const context=$('#expertContext')?.value||'EMag';const selected=state.expertOverrides[context]||{};const rows=(state.expertEntries||[]).filter(e=>!q||JSON.stringify([e.automation_name,e.description,e.category,e.unit,expertDescription(e)]).toLowerCase().includes(q)).slice(0,120);
  if($('#expertContextExplain'))$('#expertContextExplain').innerHTML=`<b>${contextChinese(context)}</b>：${({EMag:'几何、绕组、激励、电磁FEA与波形计算参数。普通设计优先使用上方“工程参数编辑器”。',Therm:'热网络、冷却、边界条件和瞬态/稳态热计算参数。',Lab:'转矩-转速、效率图、损耗图、工作点与Duty Cycle等Lab模型设置。',Mechanical:'转子机械强度、电磁力与NVH相关设置。'})[context]||''}`;
  box.innerHTML=rows.map(e=>{const name=e.automation_name,checked=Object.prototype.hasOwnProperty.call(selected,name),value=checked?selected[name]:(e.current_value??'');return `<div class="expert-param-row"><label class="expert-enable"><input type="checkbox" data-expert-enable="${esc(name)}" ${checked?'checked':''}><span><b>${esc((state.language==='en'?(e.metadata?.label_en||''):(e.metadata?.label_zh||''))||expertDescription(e).split('。')[0])}${e.reviewed?' ✓':''}</b><small>${esc(name)}${e.unit?' · '+esc(e.unit):''}</small></span></label><p>${esc(expertDescription(e))}${e.reviewed?` <span class="parameter-state-chip">${uiText('已审核','Reviewed')}</span>`:` <span class="parameter-state-chip warning">${uiText('未审核原生参数','Unreviewed native parameter')}</span>`}</p><input data-expert-value="${esc(name)}" value="${esc(value)}" ${checked?'':'disabled'}></div>`}).join('')||`<div class="help-empty"><b>${uiText('当前没有已加载的专家参数','No expert parameters loaded')}</b><span>${uiText('普通用户无需配置。只有从目标Motor-CAD版本导入Automation Parameter Names后，这里才会出现长尾参数。','Normal users do not need this area. Long-tail parameters appear after importing Automation Parameter Names from the target Motor-CAD version.')}</span></div>`;
  $$('[data-expert-enable]').forEach(c=>c.addEventListener('change',()=>{const name=c.dataset.expertEnable,input=document.querySelector(`[data-expert-value="${CSS.escape(name)}"]`);input.disabled=!c.checked;if(c.checked){const raw=input.value;state.expertOverrides[context][name]=raw!==''&&Number.isFinite(Number(raw))?Number(raw):raw}else delete state.expertOverrides[context][name];updateTaskPreview()}));
  $$('[data-expert-value]').forEach(i=>i.addEventListener('change',()=>{if(!i.disabled){const raw=i.value;state.expertOverrides[context][i.dataset.expertValue]=raw!==''&&Number.isFinite(Number(raw))?Number(raw):raw;updateTaskPreview()}}));if($('#expertParamStatus'))$('#expertParamStatus').textContent=state.expertEntries.length?uiText(`已加载 ${state.expertEntries.length} 个 ${contextChinese(context)} 原生参数；默认折叠，建议仅调有明确依据的参数。`,`Loaded ${state.expertEntries.length} native ${context} parameters; keep defaults unless explicitly required.`):uiText('尚未加载专家参数；普通用户可忽略本区域。','No expert parameters loaded; normal users can ignore this section.');
};
function solverControlDescription(c){const n=String(c.automation_name||'').toLowerCase();if(n.includes('torquepointspercycle'))return '转矩波形每电周期采样点数；默认值通常已兼顾精度和速度。';if(n.includes('torquenumbercycles'))return '用于转矩求解的电周期数量；增加周期数可帮助稳态结果，但计算时间增加。';if(n.includes('backemf'))return '控制反电动势计算。需要反电动势波形/谐波时启用。';if(n.includes('cogging'))return '控制齿槽转矩计算。';if(n.includes('demag'))return '控制永磁体退磁计算。';if(n.includes('inductance'))return '控制电感/Ld/Lq计算。';if(n.includes('shortcircuit'))return '控制短路工况分析。';if(n.includes('transient'))return '热瞬态求解的时间设置。';return c.description||'Motor-CAD官方示例中的高频求解控制。未启用时沿用模板默认值。'}
renderSolverControls=function(){
  const box=$('#solverControlFields');if(!box||!state.registry)return;const context=$('#expertContext')?.value||'EMag',controls=state.registry.solver_controls?.contexts?.[context]||[],selected=state.solverSettings[context]||{};
  box.innerHTML=controls.map(c=>{const name=c.automation_name,enabled=Object.prototype.hasOwnProperty.call(selected,name),value=enabled?selected[name]:(c.default??'');let input='';if(c.type==='boolean')input=`<input type="checkbox" data-solver-value="${esc(name)}" ${value===true?'checked':''} ${enabled?'':'disabled'}>`;else if(c.type==='enum'&&Array.isArray(c.options)&&c.options.length)input=`<select data-solver-value="${esc(name)}" ${enabled?'':'disabled'}>${c.options.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label??o.value)}</option>`).join('')}</select>`;else input=`<input data-solver-value="${esc(name)}" type="number" step="${c.type==='integer'?'1':'any'}" value="${esc(value)}" ${enabled?'':'disabled'}>`;return `<div class="solver-control-row"><label class="expert-enable"><input type="checkbox" data-solver-enable="${esc(name)}" ${enabled?'checked':''}><span><b>${esc(c.label||name)}</b><small>${esc(name)}${c.unit?' · '+esc(c.unit):''}</small></span></label><p>${esc(solverControlDescription(c))}</p>${input}</div>`}).join('')||`<p class="muted">${uiText('当前上下文没有内置求解控制；保持模板默认即可。','No built-in controls for this context; keep template defaults.')}</p>`;
  $$('[data-solver-enable]').forEach(ch=>ch.addEventListener('change',()=>{const name=ch.dataset.solverEnable,input=document.querySelector(`[data-solver-value="${CSS.escape(name)}"]`);input.disabled=!ch.checked;if(ch.checked){let v=input.type==='checkbox'?input.checked:input.value;if(input.type!=='checkbox'&&v!==''&&Number.isFinite(Number(v)))v=Number(v);state.solverSettings[context][name]=v}else delete state.solverSettings[context][name];updateTaskPreview()}));$$('[data-solver-value]').forEach(input=>input.addEventListener('change',()=>{if(!input.disabled){let v=input.type==='checkbox'?input.checked:input.value;if(input.type!=='checkbox'&&v!==''&&Number.isFinite(Number(v)))v=Number(v);state.solverSettings[context][input.dataset.solverValue]=v;updateTaskPreview()}}));
};

function materialPropertySummary(m){if(!m)return'';const p=m.properties||{};const parts=[];if(p.br_mT_typ)parts.push(`Br≈${p.br_mT_typ} mT`);if(p.hcj_kApm_min)parts.push(`Hcj≥${p.hcj_kApm_min} kA/m`);if(p.bhmax_kJpm3_typ)parts.push(`BHmax≈${p.bhmax_kJpm3_typ} kJ/m³`);if(m.thickness_mm)parts.push(`${m.thickness_mm} mm`);if(m.max_loss_wpkg_50hz_1p5t)parts.push(`P1.5/50≤${m.max_loss_wpkg_50hz_1p5t} W/kg`);if(m.temperature_class_c)parts.push(`${uiText('温度等级参考','Temperature guide')} ${m.temperature_class_c}°C`);return parts.join(' · ')}
function bilingualMaterialLabel(row){if(!row)return'';const zh=row.label_zh||row.label||row.id||'',en=row.label_en||'';if(state.language==='en')return en||zh;return en&&en!==zh?`${zh} / ${en}`:zh}
async function loadMaterialCatalog(){
  const status=$('#materialCatalogStatus'),grid=$('#materialQuickGrid');if(!grid)return;if($('#componentMaterials'))$('#componentMaterials').value='';if($('#coolingFluids'))$('#coolingFluids').value='';try{state.materialCatalog=await api(`/api/materials/catalog?language=${state.language}`);const groups={};(state.materialCatalog.materials||[]).forEach(m=>(groups[m.category]??=[]).push(m));grid.innerHTML=(state.materialCatalog.component_slots||[]).map(slot=>{const opts=groups[slot.category]||[];return `<label class="material-selector"><span>${esc(bilingualMaterialLabel(slot))} <small class="bilingual-code">${esc(slot.id)}</small></span><select data-material-slot="${esc(slot.id)}"><option value="">${uiText('沿用模板材料','Keep template material')}</option>${opts.map(m=>`<option value="${esc(m.motorcad_name||m.id)}" data-material-id="${esc(m.id)}">${esc(bilingualMaterialLabel(m))}</option>`).join('')}</select><small data-material-info="${esc(slot.id)}">${uiText('未覆盖模板材料','Template material unchanged')}</small></label>`}).join('');
  }catch(e){if(status)status.textContent=e.message;grid.innerHTML=`<pre class="error-text">${esc(e.message)}</pre>`;return}
  // Append fluid selectors separately to keep structural and coolant material mapping explicit.
  const fluids=(state.materialCatalog.materials||[]).filter(m=>m.category==='fluid');
  grid.insertAdjacentHTML('beforeend',(state.materialCatalog.fluid_slots||[]).map(slot=>`<label class="material-selector fluid"><span>${esc(bilingualMaterialLabel(slot))} <small class="bilingual-code">${esc(slot.id)}</small></span><select data-fluid-slot="${esc(slot.id)}"><option value="">${uiText('沿用模板介质','Keep template fluid')}</option>${fluids.map(m=>`<option value="${esc(m.motorcad_name||m.id)}">${esc(bilingualMaterialLabel(m))}</option>`).join('')}</select><small>${uiText('仅在对应冷却结构已存在时生效','Effective only when the corresponding cooling structure exists')}</small></label>`).join(''));
  if(status)status.innerHTML=`<b>${uiText('内置常用材料目录已加载','Common material catalog loaded')}</b><span>${esc(state.materialCatalog.notes?.[state.language]||state.materialCatalog.notes?.zh||'')}</span>`;
  const sync=()=>{const comp=[];$$('[data-material-slot]').forEach(sel=>{if(sel.value)comp.push(`${sel.dataset.materialSlot}=${sel.value}`);const selected=sel.options[sel.selectedIndex],mid=selected?.dataset?.materialId,m=(state.materialCatalog.materials||[]).find(x=>x.id===mid),info=document.querySelector(`[data-material-info="${CSS.escape(sel.dataset.materialSlot)}"]`);if(info)info.textContent=m?(materialPropertySummary(m)||uiText('公共型号；精确曲线以供应商/Motor-CAD数据库为准','Public grade; exact curves come from supplier/Motor-CAD database')):uiText('未覆盖模板材料','Template material unchanged')});const fluids=[];$$('[data-fluid-slot]').forEach(sel=>{if(sel.value)fluids.push(`${sel.dataset.fluidSlot}=${sel.value}`)});if($('#componentMaterials'))$('#componentMaterials').value=comp.join('\n');if($('#coolingFluids'))$('#coolingFluids').value=fluids.join('\n');updateTaskPreview()};
  $$('[data-material-slot],[data-fluid-slot]').forEach(sel=>sel.addEventListener('change',sync));sync();
}

