const _loadDataFactoryV011=loadDataFactory;loadDataFactory=async function(){await _loadDataFactoryV011();if(state.language==='zh'){const map={'Ingested Tasks':'已摄取任务','Curated Rows':'清洗数据行','Datasets':'数据集','Dataset Versions':'数据集版本','Versioned rows':'版本化数据行','Recent versions':'最近版本','Create new dataset':'新建数据集','No versions':'暂无版本','No datasets yet. Build the first immutable version from completed tasks.':'尚无数据集，请从已完成任务构建第一个不可变版本。','No dataset versions yet.':'尚无数据集版本。'};$$('#dataFactory .metric-card span,#dataFactory h3,#dataFactory .muted,#factoryDatasetExisting option').forEach(el=>{const v=el.textContent.trim();if(map[v])el.textContent=map[v]})}};
const _openDatasetVersionV011=openDatasetVersion;openDatasetVersion=async function(datasetId,version){await _openDatasetVersionV011(datasetId,version);if(state.language==='zh'&&$('#datasetDetail')){const replacements=[['Version','版本'],['Rows','数据行'],['Schema hash','Schema哈希'],['Content hash','内容哈希'],['Created','创建时间'],['Quality distribution','质量分布'],['Stable partitions','稳定数据分区'],['Lineage','数据血缘'],['Quality report','质量报告'],['Quarantine','隔离区'],['columns','列']];let html=$('#datasetDetail').innerHTML;replacements.forEach(([a,b])=>html=html.split(a).join(b));$('#datasetDetail').innerHTML=html}};

async function initV011(){
  state.language=window.MCS_I18N?.language||'zh';
  // Re-render key controls with operator-oriented labels after registry/template loading.
  if($('#parameterGroups'))renderParameterGroups();renderSolverControls();renderExpertParameters();renderLiveDesignPreview();
  await loadMaterialCatalog();
  try{state.viewerCatalog=await api('/api/result-viewer/catalog')}catch{}
  $('#liveBadge')?.addEventListener('click',connectSystemStream);
  $('#viewerTaskSelect')?.addEventListener('change',e=>loadViewerCases(e.target.value));$('#loadCaseViewer')?.addEventListener('click',()=>openCaseViewer());$('#viewerCaseSelect')?.addEventListener('change',()=>{if($('#viewerCaseSelect').value)openCaseViewer()});
  $('#expertContext')?.addEventListener('change',()=>{renderExpertParameters();renderSolverControls()});
  $('#languageToggle')?.addEventListener('click',async()=>{queueMicrotask(async()=>{state.language=window.MCS_I18N?.language||'zh';await loadMaterialCatalog();if(state.viewer)renderViewerModule('overview');if($('#parameterGroups'))renderParameterGroups();renderExpertParameters();renderSolverControls()})});
  $('#parameterGroups')?.addEventListener('input',renderLiveDesignPreview);$('#parameterGroups')?.addEventListener('change',renderLiveDesignPreview);
  // Correct the V0.10 typo while remaining compatible with older markup.
  const logAuto=$('#logAuto刷新');if(logAuto&&!$('#logAutoRefresh'))logAuto.id='logAutoRefresh';
}

// V0.11 operator-oriented runtime diagnostics ------------------------------------
loadPreflight=async function(deep){
  const box=$('#preflightResults');if(!box)return;
  box.innerHTML=`<div class="preflight-running"><span class="spinner-dot"></span><div><b>${deep?uiText('正在启动独立检查进程并验证 Motor-CAD…','Starting isolated preflight process and validating Motor-CAD…'):uiText('正在执行非侵入式环境检查…','Running non-invasive environment checks…')}</b><small>${deep?uiText('最多等待60秒；检查进程超时会被终止，不会卡住主服务。','Maximum 60 seconds; a timed-out checker is terminated without blocking the main service.'):uiText('不会启动 Motor-CAD。','Motor-CAD will not be launched.')}</small></div></div>`;
  try{
    const r=await api(`/api/system/preflight?deep=${deep}&timeout_s=60`),mc=r.motorcad||{},checks=mc.checks||[];
    const fail=checks.filter(c=>c.status==='FAIL').length,warn=checks.filter(c=>c.status==='WARN').length,info=checks.filter(c=>c.status==='INFO').length;
    const ready=!fail;
    const stateLabel=ready?(deep?uiText('Motor-CAD 自动化链路可用','Motor-CAD automation path ready'):uiText('基础环境可继续检查','Base environment ready for next check')):uiText('存在阻断问题','Blocking issue detected');
    const statusName=s=>({PASS:uiText('通过','PASS'),WARN:uiText('需关注','WARN'),INFO:uiText('说明','INFO'),FAIL:uiText('失败','FAIL')})[s]||s;
    box.innerHTML=`<div class="preflight-summary ${ready?'ready':'failed'}"><div><span class="eyebrow">${deep?'DEEP PREFLIGHT':'SHALLOW PREFLIGHT'}</span><h3>${stateLabel}</h3><p>${deep?uiText('深度检查只验证“能否启动并连接”，真实 EMag/Thermal/Lab 模块许可证仍以实际求解 checkout 为准。','Deep preflight verifies launch/RPC connectivity. Real EMag/Thermal/Lab module licensing is authoritative only during an actual solve.'):uiText('建议先完成浅检查；需要确认RPC链路时再执行深度检查。','Run the shallow check first, then use deep preflight only when RPC connectivity must be verified.')}</p></div><div class="preflight-counts"><b>${fail}</b><span>${uiText('失败','failed')}</span><b>${warn}</b><span>${uiText('关注','warnings')}</span><b>${info}</b><span>${uiText('说明','info')}</span></div></div><div class="preflight-group"><h3>Motor-CAD</h3>${checks.map(c=>`<div class="check-item"><span class="check-state ${esc(c.status)}">${esc(statusName(c.status))}</span><span>${esc(c.message)}</span></div>`).join('')}</div>`;
    if($('#systemInfo')&&state.health)$('#systemInfo').innerHTML=[['版本',state.health.version],['数据目录',state.health.data_dir],['模板数',state.health.templates],['最大Worker',state.health.max_workers],['Motor-CAD Python接口',state.health.solvers?.motorcad?.available?uiText('可导入','Available'):uiText('不可用','Unavailable')],['PyMotorCAD版本',state.health.solvers?.motorcad?.pymotorcad_version||'-'],['模型策略',state.health.model_policy]].map(([k,v])=>`<div class="definition-item"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');
    await loadInstallations();
  }catch(e){box.innerHTML=`<div class="preflight-summary failed"><h3>${uiText('运行检查失败','Runtime check failed')}</h3><p>${esc(e.message)}</p><small>${uiText('可到“日志与问题”页面按 Request ID/时间定位；主服务仍保持运行。','Use Logs & Issues to investigate by request/time; the main service remains available.')}</small></div>`}
};
